export interface CliffArt {
  id: string;
  tags: readonly string[];
  /** 左の端・右の端の高さ（m）。出口のわきの 2 つは、透明の側が 0 */
  edges: readonly [number, number];
  /** 上の線: 左 → 右（横 24m）に 256 点。地面からの高さ（m）。0 は何も無い所 */
  top: readonly number[];
  /** 出口の側（C-19 は右、C-20 は左）と、何も無い範囲 [始め, 終わり]（m） */
  exit: 'left' | 'right' | null;
  empty: readonly [number, number] | null;
  /** 図集（cliffs_atlas_v1）の中の範囲 [u0, v0, u1, v1]。g = 範囲の下の端から地面の線までの割合、hM = 範囲の高さ（m） */
  rect: readonly [number, number, number, number];
  g: number;
  hM: number;
  /** 凹凸（明るさから。96 × 36、上の行から。-127〜127 = 奥〜手前）。base64 の Int8Array */
  relief: string;
  mean: readonly [number, number, number];
}

